package helper

import (
	"encoding/hex"
	"strings"
	"testing"

	"github.com/ethereum/go-ethereum/common"
	"github.com/stretchr/testify/require"
)

func TestParseStateSyncDataDeposit(t *testing.T) {
	rawData := ""
	data, err := hex.DecodeString(strings.TrimPrefix(rawData, "0x"))
	require.NoError(t, err)

	stateData, err := ParseStateSyncData(data)
	require.NoError(t, err)
	require.Equal(t, StateSyncEventDeposit, stateData.EventType)
	require.Equal(t, common.HexToAddress("0x032017411f4663b317fe77c257d28d5cd1b26e3d"), stateData.RootToken)
}

func TestParseStateSyncDataMap(t *testing.T) {
	rawData := ""
	data, err := hex.DecodeString(strings.TrimPrefix(rawData, "0x"))
	require.NoError(t, err)

	stateData, err := ParseStateSyncData(data)
	require.NoError(t, err)
	require.Equal(t, StateSyncEventMapToken, stateData.EventType)
	//require.Equal(t, common.HexToAddress("0x032017411f4663b317fe77c257d28d5cd1b26e3d"), stateData.RootToken)
}
